exports["VERCEL_RUN_MAX_DURATION_SEC"] = VERCEL_RUN_MAX_DURATION_SEC;
exports["RUN_BUDGET_SHARED_MS"] = RUN_BUDGET_SHARED_MS;
exports["RUN_BUDGET_LOCAL_MS"] = RUN_BUDGET_LOCAL_MS;
